CREATE OR REPLACE FUNCTION public.cw_is_monitor_owner(_uid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_global_superadmin(_uid) AND EXISTS (SELECT 1 FROM public.user_accounts a WHERE a.auth_user_id=_uid AND a.person_id='c08e66f8-e4a7-489f-a773-60d5bf3ac6c6'::uuid AND a.is_active AND a.verified_at IS NOT NULL) $$;
REVOKE ALL ON FUNCTION public.cw_is_monitor_owner(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.cw_is_monitor_owner(uuid) TO authenticated,service_role;
CREATE TABLE public.contract_watch_monitor (
 mailbox text PRIMARY KEY CHECK(mailbox='thomas.treffen@mcsservice.no'), company_id uuid NOT NULL DEFAULT 'a0000000-0000-0000-0000-000000000001' CHECK(company_id='a0000000-0000-0000-0000-000000000001'::uuid), auto_enabled boolean NOT NULL DEFAULT false, commissioned_at timestamptz, started_at timestamptz NOT NULL DEFAULT now(), lease_id uuid, lease_until timestamptz, last_attempt_at timestamptz, last_ok_at timestamptz, last_error text, paused_reason text, retry_at timestamptz, failure_count integer NOT NULL DEFAULT 0
);
GRANT ALL ON public.contract_watch_monitor TO service_role;
ALTER TABLE public.contract_watch_monitor ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.contract_watch_cursors (mailbox text NOT NULL REFERENCES public.contract_watch_monitor(mailbox),folder text NOT NULL CHECK(folder IN ('inbox','sentitems')),folder_id text,next_url text,last_ok_at timestamptz,PRIMARY KEY(mailbox,folder));
GRANT ALL ON public.contract_watch_cursors TO service_role;
ALTER TABLE public.contract_watch_cursors ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.contract_watch_message_queue (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),mailbox text NOT NULL REFERENCES public.contract_watch_monitor(mailbox),message_key text NOT NULL CHECK(length(message_key)=64),graph_id text NOT NULL CHECK(length(graph_id)<=2048),conversation_id text,folder text NOT NULL CHECK(folder IN ('inbox','sentitems')),message_at timestamptz,state text NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','done','removed','blocked')),created_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL DEFAULT (now()+interval '7 days'),UNIQUE(mailbox,message_key));
GRANT ALL ON public.contract_watch_message_queue TO service_role;
ALTER TABLE public.contract_watch_message_queue ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.contract_watch_followups (commitment_id uuid PRIMARY KEY REFERENCES public.contract_watch_commitments(id) ON DELETE CASCADE,owner_id uuid NOT NULL,company_id uuid NOT NULL CHECK(company_id='a0000000-0000-0000-0000-000000000001'::uuid),resolution text CHECK(resolution IN ('phone','manual')),snoozed_until timestamptz,updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.contract_watch_followups TO authenticated; GRANT ALL ON public.contract_watch_followups TO service_role;
ALTER TABLE public.contract_watch_followups ENABLE ROW LEVEL SECURITY;
CREATE POLICY cw_followup_owner ON public.contract_watch_followups FOR SELECT TO authenticated USING(owner_id=auth.uid() AND public.cw_is_monitor_owner(auth.uid()));
CREATE OR REPLACE FUNCTION public.cw_monitor_baseline_ok() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce((SELECT status='done' AND coalesce((counts->>'threads_analyzed')::int,0)>0 AND NOT EXISTS(SELECT 1 FROM jsonb_each_text(discard_reasons) d WHERE (d.key IN ('ai_batch_failed','store_failed','thread_cap','foreign_next_link_stopped') OR d.key LIKE 'folder_cap_%') AND d.value::int>0) FROM public.contract_watch_scan_runs WHERE mailbox='thomas.treffen@mcsservice.no' AND pilot_version=3 AND mode='historical_test' ORDER BY started_at DESC LIMIT 1),false) $$;
REVOKE ALL ON FUNCTION public.cw_monitor_baseline_ok() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.cw_monitor_baseline_ok() TO service_role;
CREATE OR REPLACE FUNCTION public.cw_monitor_status() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE m public.contract_watch_monitor; BEGIN IF NOT public.cw_is_monitor_owner(auth.uid()) THEN RAISE EXCEPTION 'forbidden'; END IF; SELECT * INTO m FROM public.contract_watch_monitor WHERE mailbox='thomas.treffen@mcsservice.no'; RETURN jsonb_build_object('auto_enabled',coalesce(m.auto_enabled,false),'commissioned',m.commissioned_at IS NOT NULL,'baseline_ok',public.cw_monitor_baseline_ok(),'last_attempt_at',m.last_attempt_at,'last_ok_at',m.last_ok_at,'last_error',m.last_error,'paused_reason',m.paused_reason,'retry_at',m.retry_at,'pending',(SELECT count(*) FROM public.contract_watch_message_queue WHERE state='pending' AND expires_at>now()),'implementation_ready',false); END $$;
REVOKE ALL ON FUNCTION public.cw_monitor_status() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.cw_monitor_status() TO authenticated;
CREATE OR REPLACE FUNCTION public.cw_monitor_stop() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.cw_is_monitor_owner(auth.uid()) THEN RAISE EXCEPTION 'forbidden'; END IF; UPDATE public.contract_watch_monitor SET auto_enabled=false,lease_id=null,lease_until=null,paused_reason='operator_stopped' WHERE mailbox='thomas.treffen@mcsservice.no'; INSERT INTO public.contract_watch_audit(actor,action,details) VALUES(auth.uid(),'auto_monitor_stop','{}'); END $$;
REVOKE ALL ON FUNCTION public.cw_monitor_stop() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.cw_monitor_stop() TO authenticated;
CREATE OR REPLACE FUNCTION public.cw_monitor_claim(_lease uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.cw_monitor_baseline_ok() OR NOT EXISTS(SELECT 1 FROM public.contract_watch_settings WHERE id AND enabled AND consent_at IS NOT NULL AND scope_verified_at IS NOT NULL AND allowed_mailboxes=ARRAY['thomas.treffen@mcsservice.no']::text[] AND public.cw_is_monitor_owner(consent_by)) THEN RETURN false; END IF; UPDATE public.contract_watch_monitor SET lease_id=_lease,lease_until=now()+interval '5 minutes',last_attempt_at=now() WHERE mailbox='thomas.treffen@mcsservice.no' AND auto_enabled AND commissioned_at IS NOT NULL AND paused_reason IS NULL AND (lease_until IS NULL OR lease_until<now()) AND (retry_at IS NULL OR retry_at<=now()) AND (last_attempt_at IS NULL OR last_attempt_at<now()-interval '15 minutes'); RETURN FOUND; END $$;
REVOKE ALL ON FUNCTION public.cw_monitor_claim(uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.cw_monitor_claim(uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.cw_monitor_commit_page(_lease uuid,_folder text,_folder_id text,_expected text,_next text,_messages jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE m public.contract_watch_monitor; x jsonb; current_url text; BEGIN SELECT * INTO m FROM public.contract_watch_monitor WHERE mailbox='thomas.treffen@mcsservice.no' FOR UPDATE; IF m.lease_id IS DISTINCT FROM _lease OR m.lease_until<now() OR NOT m.auto_enabled OR m.paused_reason IS NOT NULL OR NOT EXISTS(SELECT 1 FROM public.contract_watch_settings WHERE id AND enabled AND consent_at IS NOT NULL AND scope_verified_at IS NOT NULL) THEN RAISE EXCEPTION 'lease_or_gate_lost'; END IF; IF _folder NOT IN ('inbox','sentitems') OR jsonb_typeof(_messages)<>'array' OR jsonb_array_length(_messages)>25 OR _next IS NULL THEN RAISE EXCEPTION 'invalid_page'; END IF; SELECT next_url INTO current_url FROM public.contract_watch_cursors WHERE mailbox=m.mailbox AND folder=_folder; IF current_url IS DISTINCT FROM _expected THEN RAISE EXCEPTION 'cursor_changed'; END IF;
DELETE FROM public.contract_watch_message_queue WHERE mailbox=m.mailbox AND expires_at<=now();
FOR x IN SELECT value FROM jsonb_array_elements(_messages) LOOP
 IF coalesce((x->>'removed')::boolean,false) THEN UPDATE public.contract_watch_message_queue SET state='removed' WHERE mailbox=m.mailbox AND graph_id=x->>'graph_id';
 ELSE INSERT INTO public.contract_watch_message_queue(mailbox,message_key,graph_id,conversation_id,folder,message_at) VALUES(m.mailbox,x->>'message_key',x->>'graph_id',x->>'conversation_id',_folder,(x->>'message_at')::timestamptz) ON CONFLICT(mailbox,message_key) DO NOTHING; END IF;
END LOOP;
INSERT INTO public.contract_watch_cursors(mailbox,folder,folder_id,next_url,last_ok_at) VALUES(m.mailbox,_folder,_folder_id,_next,now()) ON CONFLICT(mailbox,folder) DO UPDATE SET folder_id=excluded.folder_id,next_url=excluded.next_url,last_ok_at=excluded.last_ok_at;
END $$;
REVOKE ALL ON FUNCTION public.cw_monitor_commit_page(uuid,text,text,text,text,jsonb) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.cw_monitor_commit_page(uuid,text,text,text,text,jsonb) TO service_role;
CREATE OR REPLACE FUNCTION public.cw_followup(_id uuid,_action text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.contract_watch_commitments; BEGIN IF NOT public.cw_is_monitor_owner(auth.uid()) THEN RAISE EXCEPTION 'forbidden'; END IF; SELECT * INTO c FROM public.contract_watch_commitments WHERE id=_id AND company_id='a0000000-0000-0000-0000-000000000001' AND mailbox='thomas.treffen@mcsservice.no'; IF c.id IS NULL THEN RAISE EXCEPTION 'not_found'; END IF; IF _action NOT IN ('phone','snooze','reopen') THEN RAISE EXCEPTION 'invalid_action'; END IF; INSERT INTO public.contract_watch_followups(commitment_id,owner_id,company_id,resolution,snoozed_until) VALUES(c.id,auth.uid(),c.company_id,CASE WHEN _action='phone' THEN 'phone' ELSE null END,CASE WHEN _action='snooze' THEN now()+interval '1 day' ELSE null END) ON CONFLICT(commitment_id) DO UPDATE SET resolution=excluded.resolution,snoozed_until=excluded.snoozed_until,updated_at=now(); INSERT INTO public.contract_watch_audit(actor,action,details) VALUES(auth.uid(),'followup_'||_action,jsonb_build_object('commitment_id',_id,'is_test',c.is_test)); END $$;
REVOKE ALL ON FUNCTION public.cw_followup(uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.cw_followup(uuid,text) TO authenticated;
COMMENT ON TABLE public.contract_watch_monitor IS 'Staged metadata-only incremental intake. No cron, no activation path, commissioning blocked pending AI/notification E2E proof.';
COMMENT ON TABLE public.contract_watch_message_queue IS 'IDs only, no bodies/subjects/addresses. Seven-day TTL enforced transactionally on page commit. No AI consumer enabled.';